<body>
<div class="app">
  <header>
    <h1>SERP Snippet Race Board</h1>
    <p class="sub">Compare three competing search snippets, score the fit, and turn the gap into copyable page-plan text.</p>
  </header>

  <section class="panel">
    <h2>Search setup</h2>
    <div class="grid two">
      <div>
        <label for="topic">Topic / keyword</label>
        <input id="topic" type="text" placeholder="Example: retirement tax planning checklist">
      </div>
      <div>
        <label for="audience">Audience</label>
        <input id="audience" type="text" placeholder="Example: pre-retirees with $1M+ portfolios">
      </div>
    </div>
  </section>

  <div class="grid two" style="margin-top:12px;">
    <section class="panel">
      <h2>Competing snippets</h2>
      <div id="cards"></div>
    </section>

    <section class="panel">
      <h2>Ranked board</h2>
      <div id="ranked"></div>
    </section>
  </div>

  <section class="panel" style="margin-top:12px;">
    <h2>Copyable SERP plan</h2>
    <textarea id="plan" class="planBox" placeholder="Generate the plan, then edit it here before copying."></textarea>
    <div class="actions">
      <button id="generatePlan">Generate plan</button>
      <button id="copyPlan" class="secondary">Copy plan</button>
      <button id="downloadPlan" class="secondary">Download .txt</button>
    </div>
    <div class="actions">
      <button id="fillExample" class="secondary">Load example</button>
      <button id="clearAll" class="warn">Clear board</button>
      <button id="saveNow" class="secondary">Save now</button>
    </div>
  </section>

  <p class="footerNote">Runs fully in your browser. Autosaves to this device. No external assets, libraries, logins, APIs, or tracking.</p>
</div>

<div id="toast" class="toast">Saved</div>

<script>
(function(){
  const storeKey = "serp-snippet-race-board-v1";

  const defaultState = {
    topic:"",
    audience:"",
    cards:[
      emptyCard("A"),
      emptyCard("B"),
      emptyCard("C")
    ],
    plan:""
  };

  let state = loadState();

  const fields = {
    topic: document.getElementById("topic"),
    audience: document.getElementById("audience"),
    cards: document.getElementById("cards"),
    ranked: document.getElementById("ranked"),
    plan: document.getElementById("plan")
  };

  function emptyCard(label){
    return {
      label,
      title:"",
      snippet:"",
      scores:{clarity:3,intent:3,freshness:3,cta:3},
      notes:""
    };
  }

  function loadState(){
    try{
      const saved = JSON.parse(localStorage.getItem(storeKey));
      if(!saved || !Array.isArray(saved.cards)) return structuredClone(defaultState);
      while(saved.cards.length < 3) saved.cards.push(emptyCard(String.fromCharCode(65 + saved.cards.length)));
      saved.cards = saved.cards.slice(0,3).map((card,i)=>({
        label: card.label || String.fromCharCode(65+i),
        title: card.title || "",
        snippet: card.snippet || "",
        scores: {
          clarity: Number(card.scores?.clarity ?? 3),
          intent: Number(card.scores?.intent ?? 3),
          freshness: Number(card.scores?.freshness ?? 3),
          cta: Number(card.scores?.cta ?? 3)
        },
        notes: card.notes || ""
      }));
      return {
        topic: saved.topic || "",
        audience: saved.audience || "",
        cards: saved.cards,
        plan: saved.plan || ""
      };
    }catch(e){
      return structuredClone(defaultState);
    }
  }

  function saveState(){
    localStorage.setItem(storeKey, JSON.stringify(state));
  }

  function total(card){
    return card.scores.clarity + card.scores.intent + card.scores.freshness + card.scores.cta;
  }

  function pct(card){
    return Math.round((total(card) / 20) * 100);
  }

  function sortedCards(){
    return state.cards
      .map((card,index)=>({card,index,score:total(card)}))
      .sort((a,b)=> b.score - a.score || a.index - b.index);
  }

  function scoreLabel(key){
    return {
      clarity:"Clarity",
      intent:"Intent",
      freshness:"Angle",
      cta:"CTA"
    }[key];
  }

  function escapeHtml(str){
    return String(str || "").replace(/[&<>"']/g, m => ({
      "&":"&amp;",
      "<":"&lt;",
      ">":"&gt;",
      '"':"&quot;",
      "'":"&#039;"
    }[m]));
  }

  function render(){
    fields.topic.value = state.topic;
    fields.audience.value = state.audience;
    fields.plan.value = state.plan;
    renderCards();
    renderRanked();
  }

  function renderCards(){
    fields.cards.innerHTML = state.cards.map((card,i)=>`
      <article class="card">
        <div class="cardTop">
          <span class="badge">Snippet ${escapeHtml(card.label)}</span>
          <span class="total">${total(card)}/20</span>
        </div>

        <label for="title-${i}">Title</label>
        <input id="title-${i}" type="text" data-card="${i}" data-field="title" value="${escapeHtml(card.title)}" placeholder="Paste competing title">

        <label for="snippet-${i}" style="margin-top:10px;">Snippet</label>
        <textarea id="snippet-${i}" data-card="${i}" data-field="snippet" placeholder="Paste competing snippet">${escapeHtml(card.snippet)}</textarea>

        <div style="margin-top:10px;">
          ${["clarity","intent","freshness","cta"].map(key=>`
            <div class="scoreRow">
              <span>${scoreLabel(key)}</span>
              <input type="range" min="0" max="5" step="1" data-card="${i}" data-score="${key}" value="${card.scores[key]}">
              <span class="scoreVal">${card.scores[key]}</span>
            </div>
          `).join("")}
        </div>

        <label for="notes-${i}" style="margin-top:10px;">Gap / opportunity note</label>
        <textarea id="notes-${i}" data-card="${i}" data-field="notes" placeholder="Example: Good promise, but weak CTA and generic angle.">${escapeHtml(card.notes)}</textarea>
      </article>
    `).join("");
  }

  function renderRanked(){
    const rows = sortedCards();

    fields.ranked.innerHTML = rows.map((row,rank)=>{
      const c = row.card;
      const weak = weakestScore(c);
      const title = c.title.trim() || "Untitled snippet";
      const snippet = c.snippet.trim() || "No snippet entered yet.";
      return `
        <article class="rankCard">
          <div class="rankHead">
            <div>
              <span class="badge">#${rank+1} · ${escapeHtml(c.label)}</span>
            </div>
            <div class="total">${row.score}/20</div>
          </div>
          <div class="rankTitle">${escapeHtml(title)}</div>
          <p class="snippet">${escapeHtml(snippet)}</p>
          <div class="barWrap" aria-label="score bar">
            <div class="bar" style="width:${pct(c)}%"></div>
          </div>
          <div class="mini">${pct(c)}% fit · weakest area: ${scoreLabel(weak)}</div>
          <div class="chips">
            <span class="chip">Clarity ${c.scores.clarity}/5</span>
            <span class="chip">Intent ${c.scores.intent}/5</span>
            <span class="chip">Angle ${c.scores.freshness}/5</span>
            <span class="chip">CTA ${c.scores.cta}/5</span>
          </div>
        </article>
      `;
    }).join("");
  }

  function weakestScore(card){
    const entries = Object.entries(card.scores);
    entries.sort((a,b)=>a[1]-b[1]);
    return entries[0][0];
  }

  function strongestScore(card){
    const entries = Object.entries(card.scores);
    entries.sort((a,b)=>b[1]-a[1]);
    return entries[0][0];
  }

  function averageScore(key){
    const sum = state.cards.reduce((acc,c)=>acc + c.scores[key],0);
    return +(sum / state.cards.length).toFixed(1);
  }

  function boardWeakness(){
    const keys = ["clarity","intent","freshness","cta"];
    keys.sort((a,b)=>averageScore(a)-averageScore(b));
    return keys[0];
  }

  function buildPlan(){
    const rows = sortedCards();
    const winner = rows[0].card;
    const second = rows[1].card;
    const weak = boardWeakness();
    const winnerStrong = strongestScore(winner);

    const topic = state.topic.trim() || "[topic]";
    const audience = state.audience.trim() || "[audience]";
    const winnerTitle = winner.title.trim() || "[best competing title]";
    const winnerSnippet = winner.snippet.trim() || "[best competing snippet]";

    const rankedText = rows.map((row,idx)=>{
      const c = row.card;
      return `${idx+1}. Snippet ${c.label} — ${row.score}/20
   Title: ${c.title.trim() || "[blank]"}
   Scores: clarity ${c.scores.clarity}/5, intent ${c.scores.intent}/5, angle ${c.scores.freshness}/5, CTA ${c.scores.cta}/5
   Gap note: ${c.notes.trim() || "[none]"}`;
    }).join("\n");

    const notes = state.cards
      .map(c => c.notes.trim())
      .filter(Boolean);

    return `SERP snippet race plan

Topic / keyword
${topic}

Audience
${audience}

Current ranking
${rankedText}

Winning pattern to beat
Snippet ${winner.label} is strongest at ${total(winner)}/20.
Its strongest dimension is ${scoreLabel(winnerStrong)}.
Title to study: ${winnerTitle}
Snippet to study: ${winnerSnippet}

Main gap to exploit
The board's weakest shared dimension is ${scoreLabel(weak)}.
Build the marketing page around a sharper ${scoreLabel(weak).toLowerCase()} than the competing snippets.

Recommended title direction
Lead with the topic, name the audience, and add one concrete outcome.
Formula: ${topic} for ${audience}: [specific outcome or useful promise]

Recommended meta snippet direction
Use one sentence for the problem, one sentence for the payoff, and a soft CTA.
Formula: Compare the key options, spot the common mistakes, and use this guide to choose the next step with more confidence.

Angle notes
${notes.length ? notes.map(n => "- " + n).join("\n") : "- Add competitor gaps here after reviewing the snippets."}

CTA fit
Make the CTA match search intent. If the query is research-heavy, use "Compare options" or "Get the checklist." If the query is purchase-ready, use "Book a consult," "Start quote," or "See pricing."

Page brief
- Open with the user's actual search problem.
- Show why existing answers are incomplete or generic.
- Add a quick comparison table or decision path.
- Include proof, examples, or constraints the competitors skip.
- End with a CTA that feels like the next logical step, not a hard sell.`;
  }

  function showToast(message){
    const toast = document.getElementById("toast");
    toast.textContent = message;
    toast.classList.add("show");
    setTimeout(()=>toast.classList.remove("show"),1400);
  }

  function downloadText(filename, text){
    const blob = new Blob([text], {type:"text/plain;charset=utf-8"});
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  function loadExample(){
    state = {
      topic:"retirement tax planning checklist",
      audience:"pre-retirees with $1M+ portfolios",
      cards:[
        {
          label:"A",
          title:"Retirement Tax Planning Checklist for 2026",
          snippet:"Use this checklist to reduce taxable income, plan Roth conversions, and avoid common retirement tax mistakes.",
          scores:{clarity:5,intent:5,freshness:3,cta:3},
          notes:"Strong intent match, but the angle feels standard."
        },
        {
          label:"B",
          title:"How to Pay Less Tax in Retirement",
          snippet:"Learn strategies retirees use to lower taxes, manage withdrawals, and keep more of their income.",
          scores:{clarity:4,intent:4,freshness:2,cta:2},
          notes:"Broad and clickable, but less specific to checklist intent."
        },
        {
          label:"C",
          title:"The Hidden Retirement Tax Traps High-Net-Worth Families Miss",
          snippet:"A practical guide to Roth timing, IRMAA, RMDs, capital gains, and estate-driven tax issues before retirement.",
          scores:{clarity:4,intent:4,freshness:5,cta:4},
          notes:"Freshest angle. Could win if title includes checklist language."
        }
      ],
      plan:""
    };
    state.plan = buildPlan();
    saveState();
    render();
    showToast("Example loaded");
  }

  fields.topic.addEventListener("input", e=>{
    state.topic = e.target.value;
    saveState();
  });

  fields.audience.addEventListener("input", e=>{
    state.audience = e.target.value;
    saveState();
  });

  fields.plan.addEventListener("input", e=>{
    state.plan = e.target.value;
    saveState();
  });

  fields.cards.addEventListener("input", e=>{
    const cardIndex = e.target.dataset.card;
    if(cardIndex === undefined) return;

    const card = state.cards[Number(cardIndex)];

    if(e.target.dataset.field){
      card[e.target.dataset.field] = e.target.value;
    }

    if(e.target.dataset.score){
      card.scores[e.target.dataset.score] = Number(e.target.value);
    }

    saveState();
    renderCards();
    renderRanked();
  });

  document.getElementById("generatePlan").addEventListener("click", ()=>{
    state.plan = buildPlan();
    fields.plan.value = state.plan;
    saveState();
    showToast("Plan generated");
  });

  document.getElementById("copyPlan").addEventListener("click", async ()=>{
    const text = fields.plan.value.trim() || buildPlan();
    fields.plan.value = text;
    state.plan = text;
    saveState();

    try{
      await navigator.clipboard.writeText(text);
      showToast("Copied");
    }catch(e){
      fields.plan.focus();
      fields.plan.select();
      document.execCommand("copy");
      showToast("Copied");
    }
  });

  document.getElementById("downloadPlan").addEventListener("click", ()=>{
    const text = fields.plan.value.trim() || buildPlan();
    const safeTopic = (state.topic || "serp-plan").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"").slice(0,48);
    downloadText(`${safeTopic || "serp-plan"}.txt`, text);
    showToast("Downloaded");
  });

  document.getElementById("fillExample").addEventListener("click", loadExample);

  document.getElementById("clearAll").addEventListener("click", ()=>{
    if(!confirm("Clear this board?")) return;
    state = structuredClone(defaultState);
    saveState();
    render();
    showToast("Cleared");
  });

  document.getElementById("saveNow").addEventListener("click", ()=>{
    saveState();
    showToast("Saved");
  });

  render();
})();
</script>
</body>
</html>
